from math import exp


def sigmoid(z):
    if z >= 0:
        return 1 / (1 + exp(-z))
    ez = exp(z)
    return ez / (1 + ez)


print(sigmoid(0.0))  # 0.5
print(round(sigmoid(2.0), 4))  # 0.8808
print(sigmoid(-1000.0))  # avoids exp(1000) overflow

from math import exp, log1p


def binary_loss_from_logit(z, y):
    if y not in (0, 1):
        raise ValueError("Binary label required")
    # softplus(z) - y*z, without exp(large positive z)
    return max(z, 0) - y * z + log1p(exp(-abs(z)))


print(round(binary_loss_from_logit(0, 1), 6))  # 0.693147

import math

# ১) ২-ডি বিন্দু (2, 2)-এর ওপর Threshold পরিবর্তনের প্রভাব (w1=1, w2=1, b=-4)
w1, w2, b = 1.0, 1.0, -4.0
points = [(0.0, 0.0), (2.0, 2.0), (3.0, 3.0), (1.0, 4.0)]

for t in [0.5, 0.8]:
    cutoff = math.log(t / (1.0 - t))
    print(f"=== Threshold t={t} (Logit cutoff={cutoff:.3f}) ===")
    for x1, x2 in points:
        z = w1 * x1 + w2 * x2 + b
        p = 1.0 / (1.0 + math.exp(-z)) if z >= 0 else math.exp(z) / (1.0 + math.exp(z))
        cls = 1 if p >= t else 0
        print(f"  Point ({x1:.0f},{x2:.0f}): z={z:>4.1f}, p={p:.3f} -> Class {cls}")

# ২) শূন্য দিয়ে ভাগ (w2=0) এড়িয়ে বক্স [0, 5]x[0, 5]-এ নিরাপদ Boundary Edge Intersection
def boundary_endpoints(w1_val, w2_val, b_val, lo=0.0, hi=5.0):
    hits = []
    # অনুভূমিক বাহু: x2 = lo ও x2 = hi
    if abs(w1_val) > 1e-12:
        for x2_edge in [lo, hi]:
            x1_hit = -(w2_val * x2_edge + b_val) / w1_val
            if lo <= x1_hit <= hi:
                hits.append((round(x1_hit, 2), x2_edge))
    # খাড়া বাহু: x1 = lo ও x1 = hi
    if abs(w2_val) > 1e-12:
        for x1_edge in [lo, hi]:
            x2_hit = -(w1_val * x1_edge + b_val) / w2_val
            if lo <= x2_hit <= hi:
                hits.append((x1_edge, round(x2_hit, 2)))
    return hits

print("Vertical boundary (w1=1, w2=0, b=-2.5) hits:", boundary_endpoints(1.0, 0.0, -2.5))

